import type { Meta, StoryObj } from '@storybook/react-webpack5';
import React, { useEffect, useState } from 'react';
import { expect, userEvent, within } from 'storybook/test';
import { ZimmQuantityStepper } from '.';

const meta: Meta<typeof ZimmQuantityStepper> = {
  title: 'Commerce/ZimmQuantityStepper',
  component: ZimmQuantityStepper,
  parameters: { layout: 'padded' },
};

export default meta;

type Story = StoryObj<typeof ZimmQuantityStepper>;
type StepperArgs = React.ComponentProps<typeof ZimmQuantityStepper>;

/**
 * Local-state wrapper so a click visibly moves the rendered quantity — ZimmQuantityStepper is a
 * controlled component (see index.tsx), it never holds its own quantity state. `setQuantity`
 * matches `onDecrement`/`onIncrement`'s `(nextQuantity: number) => void` signature directly, so
 * no extra wrapper function is needed for either callback.
 *
 * CodeRabbit (local review, cumulative diff): `useState(args.quantity)` only reads the initial
 * arg once, so editing `quantity` in Storybook's own Controls panel after a story has mounted
 * had no effect — the wrapper kept displaying its own stale local value instead of the edited
 * arg. The `play` functions above (real clicks) were never affected by this, only a manual
 * Controls-panel edit was. Re-synced with a `useEffect` so both paths agree.
 */
const InteractiveStepper = (args: StepperArgs) => {
  const [quantity, setQuantity] = useState(args.quantity);
  useEffect(() => setQuantity(args.quantity), [args.quantity]);
  return <ZimmQuantityStepper {...args} quantity={quantity} onDecrement={setQuantity} onIncrement={setQuantity} />;
};

/** Mid-range: both buttons enabled. Exercises increment then decrement. */
export const Default: Story = {
  render: (args) => <InteractiveStepper {...args} />,
  args: {
    quantity: 3,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const increment = canvas.getByRole('button', { name: 'Increase quantity' });
    const decrement = canvas.getByRole('button', { name: 'Decrease quantity' });

    await expect(canvas.getByText('3')).toBeInTheDocument();

    await userEvent.click(increment);
    await expect(canvas.getByText('4')).toBeInTheDocument();

    await userEvent.click(decrement);
    await expect(canvas.getByText('3')).toBeInTheDocument();
  },
};

/** AC 1 — quantity at the lower bound: decrement is disabled and clicking it does nothing. */
export const AtMinimum: Story = {
  render: (args) => <InteractiveStepper {...args} />,
  args: {
    quantity: 1,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const decrement = canvas.getByRole('button', { name: 'Decrease quantity' });

    await expect(decrement).toHaveAttribute('aria-disabled', 'true');

    await userEvent.click(decrement);
    await expect(canvas.getByText('1')).toBeInTheDocument();

    // Increment is unaffected by the lower bound.
    await userEvent.click(canvas.getByRole('button', { name: 'Increase quantity' }));
    await expect(canvas.getByText('2')).toBeInTheDocument();
  },
};

/** AC 3 — quantity at the upper bound: increment is disabled, decrement stays enabled. */
export const AtMaximum: Story = {
  render: (args) => <InteractiveStepper {...args} />,
  args: {
    quantity: 5,
    max: 5,
    onDecrement: () => {},
    onIncrement: () => {},
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    const increment = canvas.getByRole('button', { name: 'Increase quantity' });
    const decrement = canvas.getByRole('button', { name: 'Decrease quantity' });

    await expect(increment).toHaveAttribute('aria-disabled', 'true');

    await userEvent.click(increment);
    await expect(canvas.getByText('5')).toBeInTheDocument();

    // Decrement stays enabled and functional at the upper bound.
    await userEvent.click(decrement);
    await expect(canvas.getByText('4')).toBeInTheDocument();
  },
};

/** AC 4 — fully out-of-stock / unavailable: both buttons disabled and dimmed, regardless of
 *  where quantity sits between min and max. */
export const Unavailable: Story = {
  args: {
    quantity: 3,
    max: 5,
    isUnavailable: true,
    onDecrement: () => {},
    onIncrement: () => {},
  },
};

import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmInlineMessage } from '.';

/**
 * Six stories, deliberately overlapping variant+copy in places (per this build step's own
 * brief: "your call on exact story count/naming, as long as every one of the 3 exact strings and
 * both variants gets a real story") rather than inventing a fourth, non-canonical example string:
 * `Default`/`ErrorVariant`/`PartiallyOutOfStock` cover `error`; `Warning`/`MaxQuantityReached`
 * cover `warning` — every one of the three exact copy strings (SFCC-795 §11.2) appears at least
 * once, and both variants render at least once each.
 *
 * `Success` added SFCC-795 plan step 3.3 (2026-09-18) alongside the third variant itself — the
 * discount-label copy ("20% off applied") is the one real string this variant renders in
 * production (`product-item/index.tsx`'s `discountLabel` prop), so it's used verbatim here too.
 */
const meta: Meta<typeof ZimmInlineMessage> = {
  // Elements/, not Commerce/ — per components.md's own tiebreaker ("what does this component
  // know about?"): the prop surface is variant + text only, nothing product/cart/price-specific,
  // the same generic shape as Badge/Tag/Link. Its one caller today (ProductItem) is commerce
  // context, but that doesn't make the atom itself commerce-specific.
  title: 'Elements/ZimmInlineMessage',
  component: ZimmInlineMessage,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmInlineMessage>;

/** Fully out-of-stock — error variant, exact copy #1. */
export const Default: Story = {
  args: {
    variant: 'error',
    text: 'This item is unavailable',
  },
};

/** Named for the variant itself (`ErrorVariant`, not the bare `Error` identifier — that would
 *  shadow the built-in JS `Error` global within this module), distinct copy from `Default`
 *  (partial-OOS's string) so no two stories share identical args. */
export const ErrorVariant: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Named `Warning` for the variant itself. Also the max-quantity copy — see zimmInlineMessage.css.ts
 *  for why this is `warning`, not `error`, despite the requirement text's own wording. */
export const Warning: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

/** Partial OOS — error variant, exact copy #2. */
export const PartiallyOutOfStock: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Max quantity reached — warning variant, exact copy #3. */
export const MaxQuantityReached: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

/** Discount label — success variant, the real production copy (product-item/index.tsx's
 *  `discountLabel` prop). Green, regular weight, no icon — confirmed against Marcel's direct
 *  Figma inspector pull for this exact node (zimmInlineMessage.css.ts's own docblock). */
export const Success: Story = {
  args: {
    variant: 'success',
    text: '20% off applied',
  },
};

